contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address nonOwner) public returns (bool) {
        require(nonOwner != c.owner());
        uint256 initialOwnerBalance = c.balanceOf(c.owner());
        // Attempt to trigger XBornID as non-owner; on P this reverts, on M it succeeds
        (bool success, ) = address(c).call(abi.encodeWithSignature("XBornID()"));
        uint256 afterOwnerBalance = c.balanceOf(c.owner());
        // Rule: if XBornID is called by a non-owner, the owner's balance must not increase
        assert(!success || afterOwnerBalance == initialOwnerBalance);
        return success;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address nonOwner) public payable {
        require(nonOwner != address(0));
        bool reverted;
        try c.XBornID() { reverted = false; } catch { reverted = true; }
        assert(reverted || msg.sender == c.owner());
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address newOwner) public payable {
        require(newOwner != address(0));
        require(caller != tx.origin || caller == msg.sender);
        // Make caller the owner if they are not already, to test the revert behavior
        // but we cannot change owner arbitrarily; we can only test the current owner.
        // The rule: XBornID reverts if msg.sender != owner.
        // We need to check that XBornID reverts for a non-owner.
        // Since we cannot set owner arbitrarily (only transferOwnership by current owner),
        // and we don't know who the current owner is, we must read it.
        // owner is not public, but we can infer it via the onlyOwner modifier on withdraw()?
        // But withdraw() sends ether, which is dangerous.
        // Instead, we can observe the revert behavior directly.
        // The test: we call XBornID as the test contract itself (msg.sender = this).
        // If the test contract is not the owner, it must revert.
        // But we cannot guarantee the test contract is not the owner.
        // Solution: The rule is: XBornID() reverts unless msg.sender == owner.
        // To make a general test, we need to know the owner. Since owner is not public, we cannot read it directly.
        // However, the onlyOwner modifier is used on other functions, e.g., finishDistribution.
        // finishDistribution returns a bool. We can check if a call to finishDistribution succeeds to determine if caller is owner.
        // But finishDistribution changes state (distributionFinished = true) which is irreversible.
        // transferOwnership is also onlyOwner, but it requires a non-zero address.
        // We can try to call transferOwnership(address(0)) which is a no-op but still onlyOwner. It would revert if not owner.
        // So we can determine if caller is owner by calling transferOwnership(address(0)) and seeing if it reverts.
        // Then we can test XBornID revert behavior accordingly.
        // However, the rule is simply: XBornID reverts if caller != owner.
        // We can express this as: if a call to an onlyOwner function (like transferOwnership(address(0))) reverts, then XBornID must also revert.
        // That captures the property without needing owner directly.
        bool isOwnerReverted;
        try c.transferOwnership(address(0)) { isOwnerReverted = false; } catch { isOwnerReverted = true; }
        bool reverted;
        try c.XBornID() { reverted = false; } catch { reverted = true; }
        assert(reverted == isOwnerReverted);
    }
    receive() external payable {}
}

